{
  "type": "sim",
  "engine": "dynamics1d",
  "params": [
    {
      "name": "h",
      "label": "高度 h =",
      "min": 0,
      "max": 10,
      "step": 1,
      "default": 5,
      "decimals": 0
    }
  ],
  "model": {
    "stateVar": "N",
    "init": 1,
    "steps": 10,
    "update": "N_prev2 + N_prev1 + 1",
    "consts": {
      "N_prev1": 1,
      "N_prev2": 0
    }
  },
  "regimes": [
    {
      "when": "h>=0",
      "label": "最少节点数 N(h)",
      "desc": "高度 h 的 AVL 树最少节点数，递推 N(h)=N(h-1)+N(h-2)+1，初值 N(0)=1, N(1)=2",
      "tone": "accent"
    }
  ],
  "chart": {
    "xLabel": "高度 h",
    "yLabel": "最少节点数 N(h)",
    "targetLine": {
      "value": 1.44,
      "label": "1.44 log₂(n) 上界"
    }
  }
}
